interface ShapeVisitor<R> { fun visit(c: Circle): R; fun visit(r: Rect): R }
interface Shape { fun <R> accept(v: ShapeVisitor<R>): R }

class Circle(val r: Double) : Shape {
    override fun <R> accept(v: ShapeVisitor<R>): R = v.visit(this)
}

object AreaVisitor : ShapeVisitor<Double> {
    override fun visit(c: Circle) = Math.PI * c.r * c.r
    override fun visit(r: Rect) = r.w * r.h
}
